```json
{
  "root_causes": [
    {
      "service": "ts-order-other-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, count(*) n, approx_quantile(duration/1e6, 0.95) p95_ms FROM abnormal_traces WHERE service_name='ts-order-other-service' AND span_name IN ('SELECT ts.orders_other','INSERT ts.orders_other','UPDATE ts.orders_other','DELETE ts.orders_other') GROUP BY 1,2",
          "claim": "order-other's own DB client spans (SELECT ts.orders_other) p95 rose to about 417 ms in abnormal, from about 0.4 ms in normal."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration/1e6, 0.95) p95_ms FROM normal_traces WHERE service_name='ts-order-other-service' AND span_name IN ('SELECT ts.orders_other','INSERT ts.orders_other','UPDATE ts.orders_other','DELETE ts.orders_other') GROUP BY 1,2,3",
          "claim": "Normal-period baseline for the same order-other DB client spans: p95 about 0.3 to 0.4 ms."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, round(avg(value),3) avg_v, round(max(value),3) max_v FROM abnormal_metrics WHERE service_name='ts-order-other-service' AND metric IN ('container.cpu.usage','db.client.connections.pending_requests','k8s.pod.uptime') GROUP BY 1",
          "claim": "order-other shows low CPU, zero pending DB connection requests and no uptime reset, so the DB call wait is not resource or restart driven."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-order-other-service",
      "to": "ts-admin-order-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS caller, s.service_name AS callee, count(*) n, approx_quantile(c.duration/1e6,0.95) caller_client_p95_ms, approx_quantile(s.duration/1e6,0.95) callee_server_p95_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id AND s.trace_id = c.trace_id WHERE c.attr_span_kind='Client' AND s.attr_span_kind='Server' AND c.service_name='ts-admin-order-service' AND s.service_name='ts-order-other-service' GROUP BY 1,2",
          "claim": "admin-order's client calls into order-other take about 1.2 s p95, matching order-other's server time."
        }
      ]
    },
    {
      "from": "ts-order-other-service",
      "to": "ts-security-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, approx_quantile(s.duration/1e6,0.95) callee_server_p95_ms FROM normal_traces c JOIN normal_traces s ON s.parent_span_id = c.span_id AND s.trace_id = c.trace_id WHERE c.attr_span_kind='Client' AND s.attr_span_kind='Server' AND c.service_name='ts-security-service' AND s.service_name='ts-order-other-service' GROUP BY 1,2",
          "claim": "Normally security calls order-other 42 times in the sample; in abnormal these calls vanish while security's internal check slows to about 1.3 s."
        }
      ]
    },
    {
      "from": "ts-security-service",
      "to": "ts-preserve-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS caller, s.service_name AS callee, count(*) n, approx_quantile(c.duration/1e6,0.95) caller_client_p95_ms, approx_quantile(s.duration/1e6,0.95) callee_server_p95_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id AND s.trace_id = c.trace_id WHERE c.attr_span_kind='Client' AND s.attr_span_kind='Server' AND c.service_name='ts-preserve-service' AND s.service_name='ts-security-service' GROUP BY 1,2",
          "claim": "Preserve's client call to security takes about 1.3 s p95, matching security's server span, versus about 25 ms normally."
        }
      ]
    },
    {
      "from": "ts-admin-order-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration/1e6,0.95) p95_ms FROM abnormal_traces WHERE service_name='ts-admin-order-service' AND attr_span_kind='Server' GROUP BY 1,2 ORDER BY p95_ms DESC",
          "claim": "Admin-order server endpoints (GET/DELETE/PUT adminorder) run at 1.2 to 1.9 s p95 in abnormal, reached through ui-dashboard by users."
        }
      ]
    },
    {
      "from": "ts-order-other-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) n, approx_quantile(duration/1e6,0.95) p95_ms FROM abnormal_traces WHERE service_name='loadgenerator' AND span_name LIKE '%orderOtherService/orderOther/refresh%' GROUP BY 1",
          "claim": "User requests to the order-other refresh path through ui-dashboard reach about 430 ms p95 in abnormal."
        }
      ]
    }
  ]
}
```

